/* Authored teaching scenario; no generated policy claims or external services. */
const Chamber=(()=>{
 const $=id=>document.getElementById(id);let lines={},step=0,mode='solo',sound=false,current='',audio=null,finish=null,report=false,packageChoice='balanced',busy=false;let generation=0,finalAgreement=null,downloaded=false,opening='equity',initialReporting=false,attempts=0,failures=0;
 let plenaryVotes={},committeePending=false;let customDraft=null,proposalHistory=[],reflection=['','',''],tourStep=0;let assignments=[],briefIndex=0,turnIndex=0,activeRole='k',guarantee=true,delivery=10,shocked=false,humanVotes={},plan=[10,5,5],planSaved=false,pausedForDialog=false;
 const names=['Arrive','Listen','Speak','Consult','Negotiate','Decide','Report'];
 const btn=(text,action,cls='primary')=>`<button class="${cls}" onclick="Chamber.${action.replaceAll('"','&quot;')}">${text}</button>`;
 function view(n){const seat=mode==='solo'&&assignments[0]?assignments[0].role:'k';AssemblyScene.view(n==='seat'?(seat==='chair'?'chair':seat==='k'?'seat':Roles.get(seat).name):n);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===n));$('roomLabel').textContent=n==='consult'?'INFORMAL CONSULTATIONS':n==='seat'?'YOUR DELEGATION VIEW':n==='chair'?'THE CHAIR’S ROSTRUM':'THE ASSEMBLY CHAMBER';}
 function setPanelCollapsed(collapsed){$('panel').hidden=collapsed;document.body.classList.toggle('panel-collapsed',collapsed);const control=$('panelToggle');control.setAttribute('aria-expanded',String(!collapsed));control.textContent=collapsed?'Show session controls':'Hide session controls';}
 function togglePanel(){const collapsed=!$('panel').hidden;setPanelCollapsed(collapsed);if(!collapsed)$('panel').focus();}
 function panel(title,body,actions=''){ $('panel').innerHTML=`<span class="eyebrow">${mode==='solo'?'SOLO PRACTICE':'GROUP PRACTICE · '+assignments.length+' STUDENTS'} / ${String(step+1).padStart(2,'0')}</span><h1>${title}</h1><div class="next-action">${busy?'Listen to the speech, or use Finish speech below.':step===0?'Start here: choose your practice mode, then read your role.':step===4?'Next: compose a draft, check responses, then circulate it.':step===6?'Next: reflect, download your agreement, and save it to your account.':'Next: use the action buttons in this panel to continue.'}</div>${body}<div class="actions">${actions}</div>`;setPanelCollapsed(busy);if(busy)$('panelToggle').focus();$('journey').innerHTML=names.map((n,i)=>`<span class="${i===step?'current':i<step?'done':''}"><i>${i+1}</i>${n}</span>`).join('');}
 function notify(t){$('notice').textContent=t;setTimeout(()=>$('notice').textContent='',6000);}
 function toggleSound(){sound=!sound;if(audio)audio.muted=!sound;$('soundBtn').innerHTML=`♪ <span>${sound?'Audio on':'Audio off'}</span>`;$('soundBtn').setAttribute('aria-label',sound?'Mute audio':'Enable audio');}
 function stop(){if(audio){audio.ontimeupdate=null;audio.pause();audio.onended=null;audio.onerror=null;audio=null}if(finish){const f=finish;finish=null;f()}AssemblyScene.speaking('');}
 function say(key){stop();current=key;const l=lines[key];if(!l)return Promise.resolve();$('speaker').textContent=l.speaker;$('speakerRole').textContent=l.role;$('captionText').textContent=l.text;AssemblyScene.speaking(l.speaker);$('replayBtn').disabled=false;$('skipBtn').disabled=false;$('pauseBtn').disabled=false;
  return new Promise(resolve=>{let done=false;const complete=()=>{if(done)return;done=true;finish=null;$('pauseBtn').disabled=true;$('skipBtn').disabled=true;$('audioProgress').style.width='100%';AssemblyScene.speaking('');resolve()};finish=complete;audio=new Audio(`audio/${key}.wav?v=0.4`);audio.muted=!sound;audio.ontimeupdate=()=>{$('audioProgress').style.width=`${audio.duration?audio.currentTime/audio.duration*100:0}%`};audio.onended=complete;audio.onerror=()=>{notify('Audio unavailable. Read the caption, then use Finish speech.');$('pauseBtn').disabled=true};audio.play().catch(()=>{if(done)return;notify('Press Finish speech to continue with captions.');$('pauseBtn').disabled=true});$('pauseBtn').textContent='Ⅱ';});
 }
 function pause(){if(!audio)return;if(audio.paused){audio.play().catch(()=>{});$('pauseBtn').textContent='Ⅱ'}else{audio.pause();$('pauseBtn').textContent='▶'}}
 function skip(){stop()}function replay(){if(!busy&&current)say(current)}
 async function speak(key,after){const run=generation;busy=true;panel('The floor is open',`<p>${lines[key].speaker} is speaking. Follow the caption below.</p><p class="note">You can pause, replay after the speech, or finish the speech using the caption controls.</p>`);await say(key);if(run!==generation)return;busy=false;after();}
 function start(withSound){if(!Roles.validate(mode,assignments)||assignments.some(a=>!a.ready))return;closeDialog();if(sound!==withSound)toggleSound();step=1;Diplomacy.log('Opening plenary','Agenda: equitable access to vaccines. Organization of work: evidence briefing, Committee A consultations, committee recommendation, closing plenary and implementation debrief.');updateSeat();view('chair');speak('welcome',()=>panel('First, the evidence','<p>Listen for the resources available and the constraints each delegation brings.</p>',btn('Hear the technical briefing','brief()')))}
 function brief(){AssemblyScene.screen('100 MILLION COURSES','Four delegations. One shared pool.');speak('evidence',()=>panel('National positions','<p>Public statements reveal interests, but rarely the full room for compromise.</p>',btn('Hear Nordland','north()')))}
 function north(){view('Nordland');speak('nordland',()=>panel('A donor’s condition','<p>Nordland links financing to public reporting. Listen next for what the producer needs.</p>',btn('Hear Meridia','producer()')))}
 function producer(){view('Meridia');speak('meridia',()=>{step=2;turnIndex=0;roleTurn()})}
 function owner(id){const i=assignments.findIndex(a=>a.role===id);return i<0?'Scripted actor':mode==='solo'?'You':`Student ${i+1}`}
 function human(id){return assignments.some(a=>a.role===id)}
 function updateSeat(){const el=$('seatIdentity');if(el)el.textContent=mode==='solo'&&assignments[0]?Roles.get(assignments[0].role).name.toUpperCase():assignments.length?`${assignments.length} STUDENTS`:'CHOOSE YOUR ROLE';}
 function roleTurn(){const people=assignments.filter(a=>a.role!=='chair');if(turnIndex>=people.length){if(human('chair')){activeRole='chair';view('chair');panel('Chair: summarize the room','<p>Invite the delegations to consult on financing and accountability. You facilitate the discussion; you do not make a national demand.</p>',btn('Open informal consultations','consult()'))}else{step=3;panel('Move to consultation','<p>The opening statements are complete. The next task is to connect financing with accountability.</p>',btn('Enter consultation','consult()'))}return}activeRole=people[turnIndex].role;const r=Roles.get(activeRole);view(activeRole==='k'?'seat':r.name);panel(`${owner(activeRole)}: ${r.name}`,`<p>${r.task}</p><p class="note">${r.constraint}</p><p>${human('chair')?owner('chair')+' (Chair): recognize this delegation after it requests the floor.':'Request the floor before presenting your intervention.'}</p>`,btn('Request the floor','floor()')+btn('Read this role brief','roleBrief("'+activeRole+'")','secondary'))}
 function floor(){view('chair');const id=activeRole;speak('recognize_'+id,intervention)}
 function intervention(){const r=Roles.get(activeRole);view(activeRole==='k'?'seat':r.name);const choices={k:[['Propose an equitable 35% share','equity'],['Open with a 50% demand','national']],n:[['Insist on public reporting','report'],['Invite discussion of accountability','discuss']],m:[['Require a purchase guarantee','guarantee'],['Leave the guarantee unresolved','unresolved']],p:[['Request 10m for delivery','delivery'],['Leave delivery funding unresolved','unresolved']]};panel(`${r.name}: your intervention`,`<p>${owner(activeRole)}, speak aloud in your role, then select the position to record. Synthetic narration voices the selected intervention.</p><p class="note">${r.line}</p>`,btn('Write and deliver my own statement','originalStatement()')+choices[activeRole].map(([label,c])=>btn(label,'statement("'+c+'")','choice')).join(''))}
 function statement(choice){if(activeRole==='k'){opening=choice;packageChoice=choice==='national'?'national':'balanced'}if(activeRole==='n'&&choice==='report')report=true;if(activeRole==='m')guarantee=choice==='guarantee';if(activeRole==='p')delivery=choice==='delivery'?10:5;const key=activeRole==='k'?'statement_'+choice:'role_'+activeRole+'_'+choice;speak(key,()=>{turnIndex++;roleTurn()})}
 function consult(){step=3;view('consult');speak('consult',()=>panel('A possible trade','<p><b>35m credits</b> of donor financing, including <b>10m</b> for delivery, in return for quarterly public reporting.</p>',btn('Accept public reporting','amend(true)','choice')+btn('Reject the reporting condition','amend(false)','choice')))}
 function amend(yes){report=yes;initialReporting=yes;speak(yes?'agree':'reject',()=>panel('An interruption','<p>A new supply update has reached the Secretariat. Negotiations must respond to changing facts.</p>',btn('Return to the chamber','shock()')))}
 function shock(){Diplomacy.log('Secretariat inject','Fictional manufacturing disruption: common pool falls from 100m to 80m courses; Meridia mandate rises to 30%.');shocked=true;step=4;view('overview');AssemblyScene.screen('SUPPLY UPDATE: 80 MILLION','A manufacturing disruption changes the negotiation.','SECRETARIAT BRIEFING');speak('shock',packages)}
 function packages(){panel('Revise the package',`<p>The pool fell to <b>80m courses</b>. Meridia now requires 30%. Discuss the text together before circulating it.</p><p class="note">Reporting: ${report?'included':'unresolved'} · Guarantee: ${guarantee?'included':'unresolved'} · Delivery: ${delivery}m credits. Donor fund: ${state().fund}m.</p>`,btn('Record a question or conditional offer','workspace("participate")','secondary')+btn('Negotiate resolution paragraphs','workspace("draft")')+btn('Compose your own proposal','proposalEditor()')+btn('Review negotiation record','negotiationRecord()','secondary')+btn('35 / 20 / 30 / 15% + guarantee','choose("balanced")','choice')+btn('50 / 20 / 15 / 15% + guarantee','choose("national")','choice')+btn(report?'Remove public reporting':'Include public reporting','reporting()','secondary')+btn(delivery===10?'Reduce delivery support to 5m':'Include 10m delivery support','deliveryChange()','secondary')+`<p class="micro-note">Allocation order: Kitala · Nordland · Meridia · Pelagia. Both circulated packages include the purchase guarantee; unresolved opening demands can be revised here.</p>`)}
 function reporting(){report=!report;packages()}
 function deliveryChange(){delivery=delivery===10?5:10;packages()}
 function state(){const s=Lab.fresh(mode==='solo'?'solo':'class');Object.assign(s,{supply:shocked?80:100,shock:shocked,alloc:customDraft?[...customDraft.alloc]:packageChoice==='balanced'?[35,20,30,15]:[50,20,15,15],fund:customDraft?customDraft.fund:35,delivery,report,guarantee,briefed:true,consulted:[],implementation:[...plan]});return s}
 function choose(p){Diplomacy.invalidate();plenaryVotes={};committeePending=false;if(p!=='custom'){customDraft=null;packageChoice=p;guarantee=true;}const draft=state();const issue=Negotiation.validate(draft);if(issue){notify(issue);return}const prior=proposalHistory.length?proposalHistory[proposalHistory.length-1].terms:null;proposalHistory.push({number:(proposalHistory.at(-1)?.number||0)+1,terms:{alloc:[...draft.alloc],fund:draft.fund,delivery:draft.delivery,report:draft.report,guarantee:draft.guarantee},changes:Negotiation.changes(prior,draft),result:'Circulated'});if(proposalHistory.length>40)proposalHistory.shift();humanVotes={};step=5;view('chair');AssemblyScene.screen('CONSIDERATION OF THE DRAFT','The chair invites each delegation to state its position.');speak('consensus',positionCheck)}
 function positionCheck(){const s=state();const pending=assignments.find(a=>a.role!=='chair'&&!humanVotes[a.role]);if(!pending){panel(human('chair')?'Chair: announce the result':'Establish the result','<p>All assigned delegates have recorded a position. Unassigned delegates follow their scripted mandates. The Chair has no extra vote.</p>',btn('Check consensus','decide()'));return}const r=Roles.get(pending.role),i=Lab.countries.findIndex(c=>c.id===r.id),p=Lab.position(s,i);panel(`${owner(r.id)}: ${r.name}`,`<p>State your position on the revised draft.</p><p class="note">${p.reason}</p><p>${p.yes?'Your written mandate is met. You can support or maintain an objection for discussion.':'This prototype requires you to respect your written mandate. Record an objection and return to negotiation.'}</p>`,(p.yes?btn('Support the draft','recordPosition("'+r.id+'","support")'):'')+btn('Object to the draft','recordPosition("'+r.id+'","object")','secondary')+btn('Review draft text','showDocument()','textbutton'))}
 function recordPosition(id,value){humanVotes[id]=value;positionCheck()}
 function decide(){if(!Diplomacy.ready()){notify('Review the resolution paragraphs before committee consideration.');workspace('draft');return}const s=state(),positions=Lab.countries.map((c,i)=>({...c,...Lab.position(s,i),yes:Lab.position(s,i).yes&&(!human(c.id)||humanVotes[c.id]==='support'),reason:humanVotes[c.id]==='object'?'Student delegate recorded an objection.':Lab.position(s,i).reason})),adopted=positions.every(p=>p.yes);if(proposalHistory.length)proposalHistory[proposalHistory.length-1].result=adopted?'Committee recommendation':'Objection remains';attempts++;if(!adopted)failures++;else {Diplomacy.committee();committeePending=true;plenaryVotes={};plenary();return;}speak(adopted?'adopted':'failed',()=>{if(adopted){finishSession();return}AssemblyScene.screen('CONSULTATIONS CONTINUE','An objection remains. Revise the package.');panel('Consensus not reached',positions.map(p=>`<div class="lineitem"><b>${p.yes?'✓':'!'} ${p.name}</b><p>${p.reason}</p></div>`).join(''),btn('Return to the draft','revise()'));})}
 function finishSession(){step=6;view('overview');AssemblyScene.screen('POLICY AGREEMENT ADOPTED','Review the adopted terms and download your final report.','SESSION COMPLETE');panel('Your agreement is ready.',`<p>The closing plenary has adopted the reviewed text without an objection. Your session ends here with a policy agreement report.</p><div class="mini-stat"><div><strong>4 / 4</strong><span>DELEGATIONS</span></div><div><strong>80m</strong><span>COURSES ALLOCATED</span></div></div><p class="note">Includes the adopted allocation, ${state().fund}m-credit financing commitment, delivery support, reporting, production guarantee and negotiation record.</p><p id="downloadStatus" role="status">${downloaded?'PDF download requested. Check your browser downloads.':'Review and save the agreement before starting again.'}</p>`,btn('Review negotiated resolution','workspace("draft")','secondary')+btn('Reflect on your negotiation','reflect()')+btn('Save agreement to my account','saveToAccount()','secondary')+btn('Download final agreement (PDF)','downloadAgreement()')+btn('Review policy agreement','reviewAgreement()','secondary')+btn('Open implementation plan','implementation()','secondary')+btn('Start a new simulation','restart()','secondary'))}
 function reviewAgreement(){if(!finalAgreement)return;dialog('<span class="eyebrow">FINAL ADOPTED TEXT</span><h2>Policy agreement report</h2>'+Agreement.html(finalAgreement)+btn('Download final agreement (PDF)','downloadAgreement()'))}
 function downloadAgreement(){if(!finalAgreement)return;const blob=new Blob([Agreement.pdf(finalAgreement)],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=finalAgreement.id+'-policy-agreement.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);downloaded=true;const status=$('downloadStatus');if(status)status.textContent='PDF download requested. Check your browser downloads.';notify('Policy agreement PDF sent to your browser downloads.');}
 function restart(){if(step===0){resetSession();return}dialog('<h2>Start a new simulation?</h2><p>'+(finalAgreement?(downloaded?'Your downloaded report remains on your device. A new session starts with fresh choices.':'Download your final agreement before resetting if you want to keep it.'):'This resets the current negotiation and all choices.')+'</p>'+(finalAgreement?btn('Download final agreement (PDF)','downloadAgreement()'):'')+btn('Start fresh','resetSession()','secondary')+btn('Keep this session','closeDialog()','textbutton'))}
 function closeDialog(){$('dialog').close();if(pausedForDialog&&audio){audio.play().catch(()=>{});$('pauseBtn').textContent='Ⅱ'}pausedForDialog=false;}
 function resetSession(){Diplomacy.reset();plenaryVotes={};committeePending=false;generation++;pausedForDialog=false;stop();closeDialog();step=0;mode='solo';current='';busy=false;report=false;packageChoice='balanced';customDraft=null;proposalHistory=[];reflection=['','',''];finalAgreement=null;downloaded=false;opening='equity';initialReporting=false;attempts=0;failures=0;assignments=[];briefIndex=0;turnIndex=0;humanVotes={};shocked=false;guarantee=true;delivery=10;plan=[10,5,5];planSaved=false;updateSeat();AssemblyScene.speaking('');AssemblyScene.screen('EQUITABLE ACCESS','A shared challenge. A negotiated response.');view('overview');$('speaker').textContent='Welcome, delegate';$('speakerRole').textContent='Your seat is waiting';$('captionText').textContent='Negotiate together. Reach agreement. Take your final policy report with you.';$('audioProgress').style.width='0%';['pauseBtn','replayBtn','skipBtn'].forEach(id=>$(id).disabled=true);$('notice').textContent='';welcome();window.scrollTo(0,0);}
 function revise(){Diplomacy.invalidate();committeePending=false;plenaryVotes={};step=4;view('overview');packages()}
 function dialog(html){if(audio&&!audio.paused){audio.pause();pausedForDialog=true;$('pauseBtn').textContent='▶'}$('dialogBody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();$('dialogBody').parentElement.scrollTop=0;}
 function debrief(){dialog('<h2>What changed the outcome?</h2><p>Reporting unlocked donor support. A purchase guarantee and revised allocation addressed the producer’s constraint. Delivery funding made the package relevant to Pelagia.</p><p>Kitala’s 35% share yields 28m courses after the shock, compared with 35m before it. Agreement does not automatically meet health need.</p><h3>Discuss with your class</h3><ol><li>Which clause created the most room for compromise?</li><li>How did domestic constraints shape international positions?</li><li>What could fail between adoption and delivery?</li></ol><p>This is an authored learning scenario, not a prediction of country behavior.</p>')}
 function roleContent(id){const r=Roles.get(id);return `<span class="eyebrow">${r.type} · ${r.tag}</span><h2>${r.name}</h2><p class="note">${r.task}</p><h3>Priorities</h3><p>${r.priority}</p><h3>Constraints & negotiating mandate</h3><p>${r.constraint}</p><h3>Evidence briefing</h3><p>${r.evidence}</p><h3>Authority & limits</h3><p>${r.power}</p><h3>Possible bargaining approach</h3><p>${r.trade}</p><p class="micro-note">Country names, financial units and numeric thresholds are fictional teaching assumptions. A shared-screen briefing is visible to the room; it is not a confidential online channel.</p>`}
 function roleBrief(id){dialog(roleContent(id)+btn('Return to simulation','closeDialog()','secondary'))}
 function delegate(name){const r=Roles.all.find(c=>c.name===name);if(r)roleBrief(r.id)}
 function roster(){if(!assignments.length){notify('Choose Solo practice or Group practice first.');return}dialog('<h2>Your participant roles</h2>'+assignments.map((a,i)=>btn('Student '+(i+1)+' · '+Roles.get(a.role).name,'roleBrief("'+a.role+'")','choice')).join('')+'<p>Unassigned roles are scripted actors. The Chair facilitates and has no separate country vote.</p>'+btn('Return to simulation','closeDialog()','secondary'))}
 function implementation(){if(!finalAgreement)return;const s=state();s.adopted=true;const o=Lab.outcome(s);dialog('<span class="eyebrow">OPTIONAL FOLLOW-UP · SAME SIMULATION</span><h2>Implementation plan</h2><p>Explore delivery in Kitala after adoption. These settings are a planning exercise, not new negotiated clauses.</p><p class="note">Budget: <b>'+o.budget+'m credits</b> = 20m domestic + '+s.fund+'m donor − '+delivery+'m Pelagia support. Your adopted allocation remains '+o.received+'m courses.</p>'+['Cold chain & storage','Delivery teams','Monitoring & coordination'].map((t,i)=>'<label class="plan-field">'+t+' (million credits)<input id="plan'+i+'" type="number" min="0" max="45" step="1" value="'+plan[i]+'"></label>').join('')+'<p id="planError" role="alert"></p>'+btn('Update implementation estimate','savePlan()')+'<div class="note">Saved plan: '+o.spent+'m credits. Illustrative delivery: <b>'+o.delivered.toFixed(1)+'m courses</b>; remaining need: '+o.gap.toFixed(1)+'m.</div><details><summary>Model assumptions</summary><p>Readiness starts at 30%; each cold-chain credit adds 1.5 percentage points up to 20 credits, each team credit adds 1.5 points up to 20, and monitoring adds 1 point up to 10. Readiness is capped at 100%. Delivered courses = allocation × readiness. These coefficients are illustrative, not empirically calibrated.</p></details>'+btn('Return to simulation','closeDialog()','secondary')+'<p class="micro-note">Update the estimate to save edits before returning. Returning keeps your roles, agreement and saved plan.</p>')}
 function savePlan(){const v=[0,1,2].map(i=>Number($('plan'+i).value));const max=Lab.outcome(state()).budget;if(v.some(n=>!Number.isFinite(n)||!Number.isInteger(n)||n<0)||v.reduce((a,b)=>a+b,0)>max){$('planError').textContent='Use non-negative whole credits totaling no more than '+max+'m.';return}plan=v;planSaved=true;finalAgreement.implementation=Lab.outcome({...state(),adopted:true});downloaded=false;implementation()}
 function showDocument(){if(finalAgreement){reviewAgreement();return}const s=state();dialog(`<span class="eyebrow">WORKING TEXT · TEACHING DRAFT</span><h2>Equitable access to vaccines</h2><ol><li>Allocate the shared pool: Kitala ${s.alloc[0]}%, Nordland ${s.alloc[1]}%, Meridia ${s.alloc[2]}%, Pelagia ${s.alloc[3]}%.</li><li>Provide ${s.fund}m credits of donor financing, including ${delivery}m for delivery.</li><li>${report?'Include':'Do not include'} quarterly public reporting.</li><li>${guarantee?'Provide a production purchase guarantee.':'Production guarantee remains unresolved.'}</li></ol><p>This document previews the package choices in this exercise. It is not an official WHO resolution.</p>`)}
 function showAbout(){dialog('<h2>ASSEMBLY</h2><p><b>Project vision: A Hybrid Human-AI Simulation Platform for Global Health Diplomacy Education for University Students.</b></p><p>An independent, WHO-inspired funding prototype: a stylized 3D chamber, authored synthetic speech, matching captions, and a branching negotiation.</p><p><b>Solo:</b> select any of five roles. <b>Group:</b> 2–5 students choose distinct roles on one shared screen, read individual briefings and record their positions. Unassigned roles are scripted. A resolution workspace adds paragraph review, committee recommendation and closing plenary. The coach is rule-based; live AI and separate-device multiplayer are not yet connected.</p><p>The architecture is illustrative, not an exact reconstruction. Countries, financial units, crisis and numerical outcomes are fictional. This is not affiliated with WHO and is not yet a validated digital twin.</p><p>Audio is pre-generated synthetic narration; captions display the full current speech. No microphone is accessed or recorded.</p><p><a href="https://apps.who.int/gb/bd/pdf_files/BD_49th-en.pdf" target="_blank" rel="noopener">WHO Basic Documents, 49th edition</a> provides procedural background. Real procedures include mechanisms beyond this simplified consensus exercise.</p><p>The simulation ends in a downloadable policy agreement report. Use Start a new simulation to return to the opening screen.</p>')}

 function workspace(tab='procedure'){
  const d=Diplomacy.snapshot(),locked=d.plenary;
  const tabs=[['procedure','Journey'],['participate','Participate'],['evidence','Evidence'],['draft','Resolution'],['coach','Coach'],['record','Record'],['teaching','Teaching']];
  let body='';
  if(tab==='procedure')body='<div class="diplomacy-route">'+[['01','Opening plenary','Adopt the agenda and organization of work.'],['02','Committee A','Hear technical evidence and national positions.'],['03','Informal consultations','Review the zero draft paragraph by paragraph. Bracket unresolved wording; mark provisional agreement ad ref.'],['04','Committee recommendation','Check for objections to the full text and resource package.'],['05','Closing plenary','Review explanations of position, then confirm adoption without a vote.'],['06','Implementation and debrief','Assign responsibilities, test delivery assumptions and download the report.']].map(x=>'<article><b>'+x[0]+'</b><div><h3>'+x[1]+'</h3><p>'+x[2]+'</p></div></article>').join('')+'</div><details><summary>Who has which authority?</summary><p>Member States negotiate and decide. The Executive Board prepares the agenda and gives effect to Assembly policies. The Secretariat provides technical and administrative support. The presiding officer facilitates. Invited observers and supporting experts do not gain a Member State vote.</p><p>This exercise uses four fictional countries and one presiding role; the same student may chair committee and plenary as a classroom simplification.</p></details><details><summary>Consensus, votes and the limits of this model</summary><p>This pathway follows the handbook?s consensus approach. Consensus is adoption without a vote, not a requirement that every delegation endorse every paragraph. Explanations of position can record reservations; an explicit objection prevents this pathway from proceeding.</p><p>Real WHO rules also permit voting: one vote per Member; abstentions are excluded from members present and voting; ordinary questions generally use a majority, specified important questions two thirds. Those formal voting procedures are explained here but not simulated.</p><p>A recommendation is different from a convention or regulation. The numerical bargain in this exercise is a fictional pledge annex, not a power of WHO to allocate national stocks or compel funding.</p></details><p class="micro-note">Sources: WHO Basic Documents (49th ed.), Constitution Articles 18?23, 28 and WHA Rules 69?73; GMWHO 2025 handbook, printed pp. 4?10. The supplied edition is a historical reference, not a claim that all current rules are unchanged.</p>';
  if(tab==='participate')body='<p>Speak in your own words. Record a question, conditional offer or response for the group to discuss. These contributions do not automatically change the negotiated text or numerical commitments.</p><p class="note">Shared-screen discussion record: entries are visible to everyone at this device. This is not a live message channel between devices. Speak aloud if presenting; no microphone is recorded.</p>'+(!locked&&assignments.length?'<label class="plan-field">Participant role<select id="contributionRole">'+assignments.map(a=>'<option>'+Roles.get(a.role).name+'</option>').join('')+'</select></label><label class="plan-field">Contribution<select id="contributionKind">'+['National statement','Question','Conditional offer','Response','Chair summary'].map(k=>'<option>'+k+'</option>').join('')+'</select></label><label class="reflection-field">Your contribution<textarea id="contributionText" maxlength="1000" placeholder="Our priority is... Our evidence is... We could support... if..."></textarea></label><p id="contributionError" role="alert"></p>'+btn('Add to the discussion record','saveContribution()'):'<p>'+ (locked?'The negotiation record is closed.':'Choose your participant roles first to contribute.')+'</p>')+'<h3>Discussion record</h3>'+(d.contributions.length?d.contributions.map(c=>'<article class="resolution-paragraph"><h3>'+esc(c.role)+' / '+esc(c.kind)+'</h3><p class="contribution-text">'+esc(c.text)+'</p></article>').join(''):'<p>No contributions yet. Start with your national priority and the evidence behind it.</p>');
  if(tab==='evidence')body='<p class="note">Scenario evidence is fictional. Procedural sources describe WHO institutions; they do not validate the numerical model.</p><div class="evidence-grid">'+Roles.all.map(r=>'<article><h3>'+r.name+'</h3><p>'+r.evidence+'</p><p><b>Authority:</b> '+r.power+'</p></article>').join('')+'</div><h3>Questions for the technical briefing</h3><ul><li>What is an allocation, and what is actual delivered access?</li><li>Which assumptions change after the supply disruption?</li><li>Who bears costs and who remains underserved?</li></ul><h3>Supportive actors: discussion prompts</h3><p><b>Technical expert:</b> Which delivery assumptions need evidence? <b>Civil-society observer:</b> How will underserved communities be heard? <b>Secretariat:</b> What assistance is requested and within whose authority?</p><p>These are teaching prompts, not additional voting seats or live external participants.</p>';
  if(tab==='draft')body='<p>Review the zero draft alongside the <button class="textbutton" onclick="Chamber.showDocument()">numerical pledge annex</button>. Edited paragraphs express policy recommendations; changing them does not automatically change the numeric model.</p><p class="note">Agreed ad ref means provisional wording, subject to the whole package. On this shared screen, record the discussion honestly. Unassigned actors check numerical mandates only; they do not understand free-text amendments.</p>'+d.paragraphs.map(p=>'<article class="resolution-paragraph"><div class="paragraph-heading"><h3>'+p.id+' / '+p.kind+'</h3><span class="draft-status">'+p.status+'</span></div><label class="reflection-field">Proposed wording<textarea id="text'+p.id+'" maxlength="1200" '+(locked?'disabled':'')+'>'+esc(p.text)+'</textarea></label>'+(!locked?'<label class="plan-field">Review status<select id="status'+p.id+'">'+['open','bracketed','agreed ad ref'].map(v=>'<option '+(v===p.status?'selected':'')+'>'+v+'</option>').join('')+'</select></label>'+btn('Record paragraph review','saveParagraph("'+p.id+'")','secondary'):'')+'</article>').join('')+'<p id="workError" role="alert"></p><h3>Explanations of position</h3>'+d.reservations.map(r=>'<p><b>'+esc(r.role)+':</b> '+esc(r.text)+'</p>').join('')+(!locked?'<label class="plan-field">Delegation<select id="positionRole">'+assignments.filter(a=>a.role!=='chair').map(a=>'<option>'+Roles.get(a.role).name+'</option>').join('')+'</select></label><label class="reflection-field">Reservation or explanation (does not itself block consensus)<textarea id="positionText" maxlength="600"></textarea></label>'+btn('Record explanation','savePosition()','secondary'):'')+'<p class="micro-note">Sources: GMWHO 2025 handbook, printed pp. 4?7, 9, 11?15. Original teaching text, adapted to this fictional vaccine-access scenario.</p>';
  if(tab==='coach')body='<div class="note"><b>Human?AI platform development</b><p>Live AI is not connected. The guidance below is a transparent rule-based learning coach. It cannot speak for a student, approve text, or cast a vote.</p></div><h3>Questions to strengthen your negotiation</h3><ul>'+Diplomacy.coach(assignments[0]?.role||'chair',state()).map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul><h3>Human control</h3><p>Read evidence, question automated advice and make your own decisions. A future live AI delegate will be labelled, use the scenario mandate and offer suggestions for human review. It will require a secure server connection and an agreed usage budget.</p><label class="plan-field">Implementation owner<input id="implOwner" maxlength="160" value="'+esc(d.implementation.owner)+'"></label><label class="plan-field">Target timing<input id="implDeadline" maxlength="160" value="'+esc(d.implementation.deadline)+'"></label><label class="reflection-field">Progress indicator<textarea id="implIndicator" maxlength="400">'+esc(d.implementation.indicator)+'</textarea></label>'+btn('Save planning notes to report','saveResponsibilities()','secondary');
  if(tab==='teaching')body='<h3>Suggested classroom session: 60-75 minutes</h3><ol><li>Roles and evidence: 10 minutes.</li><li>Statements and technical briefing: 10 minutes.</li><li>Paragraph review and resource negotiations: 20 minutes.</li><li>Committee and closing plenary: 10 minutes.</li><li>Implementation and debrief: 10-25 minutes.</li></ol><h3>Learning outcomes</h3><ul><li>Distinguish the authority of Member States, the Board and Secretariat.</li><li>Use evidence to explain national priorities and make a conditional offer.</li><li>Revise a disputed paragraph and distinguish provisional from final agreement.</li><li>Explain why implementation requires ownership, resources and monitoring.</li><li>Identify the limits of scripted responses and future AI advice.</li></ul><p>Assess reasoning, evidence, listening and reflection. Reaching agreement alone is not proof of learning. This prototype does not automatically grade students.</p><h3>Facilitator prompts</h3><p>Pause after the supply update: who loses access even if shares stay the same? Before plenary: does a reservation amount to an objection? After adoption: which promises still need funding, contracts or national approval?</p><p class="micro-note">The 2-5 participants share one screen. Role sheets and explanations are visible to the group. Live AI and remote synchronized rooms are not enabled.</p>';
  if(tab==='record')body='<p>Session-only record. Download or save the final agreement to preserve it.</p>'+(d.events.length?'<ol class="review-log">'+d.events.map(e=>'<li><b>'+esc(e.kind)+'</b><p>'+esc(e.text)+'</p></li>').join('')+'</ol>':'<p>The record begins when you adopt the agenda or review a paragraph.</p>')+'<p class="micro-note">The event record and reflection approach is informed by <a href="https://icons.umd.edu/about/iconsnet" target="_blank" rel="noopener">ICONSnet</a>. ASSEMBLY is independent and is not an ICONSnet integration.</p>';
  dialog('<div class="diplomacy-workspace"><span class="eyebrow">ASSEMBLY / DIPLOMACY WORKSPACE</span><h2>From discussion to resolution</h2><nav class="workspace-tabs" aria-label="Diplomacy workspace">'+tabs.map(([id,title])=>'<button class="'+(id===tab?'primary':'secondary')+'" '+(id===tab?'aria-current="page"':'')+' onclick="Chamber.workspace(\''+id+'\')">'+title+'</button>').join('')+'</nav>'+body+btn('Return to assembly','closeDialog()','secondary')+'</div>');
 }
 function saveContribution(){try{const role=$('contributionRole').value;if(!assignments.some(a=>Roles.get(a.role).name===role))throw Error('Choose an assigned participant role.');Diplomacy.contribute(role,$('contributionKind').value,$('contributionText').value);workspace('participate')}catch(e){$('contributionError').textContent=e.message}}
 function originalStatement(){const r=Roles.get(activeRole);dialog('<span class="eyebrow">YOUR VOICE / '+r.name+'</span><h2>Write your national statement</h2><p>Explain your priority, cite the scenario evidence and offer a possible compromise. Read your statement aloud to the room; it will appear in the captions and final report.</p><p class="note">'+r.constraint+'</p><label class="reflection-field">Statement<textarea id="originalStatement" maxlength="1000" placeholder="Our delegation prioritizes... We propose... We could accept... if..."></textarea></label><p id="statementError" role="alert"></p>'+btn('Take the floor with my statement','deliverOriginal()')+btn('Return to prepared options','closeDialog()','secondary'))}
 function deliverOriginal(){try{const r=Roles.get(activeRole);if(!human(activeRole)||activeRole==='chair')throw Error('A human country delegate must hold the floor.');const item=Diplomacy.contribute(r.name,'National statement',$('originalStatement').value);if(activeRole==='k')opening='original';closeDialog();stop();current='';$('speaker').textContent=r.name;$('speakerRole').textContent='Student-authored statement';$('captionText').textContent=item.text;['pauseBtn','replayBtn','skipBtn'].forEach(id=>$(id).disabled=true);AssemblyScene.speaking(r.name);panel('Your delegation has the floor','<p>Read your statement aloud, then continue. Your words are saved in the participation record. Resource commitments are entered later in the proposal editor.</p>',btn('Finish my statement','finishOriginal()'));}catch(e){$('statementError').textContent=e.message}}
 function finishOriginal(){AssemblyScene.speaking('');turnIndex++;roleTurn()}
 function saveParagraph(id){try{Diplomacy.edit(id,$('text'+id).value,$('status'+id).value,mode==='solo'?'Solo learner':'Shared-screen drafting group');workspace('draft')}catch(e){$('workError').textContent=e.message}}
 function savePosition(){try{const role=$('positionRole').value;if(!role)throw Error('Assign a human country role to record an explanation.');Diplomacy.reservation(role,$('positionText').value);workspace('draft')}catch(e){$('workError').textContent=e.message}}
 function saveResponsibilities(){Diplomacy.implementation($('implOwner').value,$('implDeadline').value,$('implIndicator').value);if(finalAgreement)finalAgreement.diplomacy=Diplomacy.reportSections();notify('Implementation notes saved for the report.');workspace('coach')}
 function plenary(){if(!committeePending)return;const pending=assignments.find(a=>a.role!=='chair'&&!plenaryVotes[a.role]);AssemblyScene.screen('CLOSING PLENARY','Committee A recommends the resolution. Final adoption is still pending.');if(pending){panel(Roles.get(pending.role).name+': closing plenary','<p>Review the committee recommendation and explanations of position. Does an objection remain to adoption without a vote?</p><p class="note">An explanation of position can qualify your support without blocking adoption. An objection returns the text to consultation.</p>',btn('No objection to adoption','plenaryPosition("'+pending.role+'",true)')+btn('Object and return to consultation','plenaryPosition("'+pending.role+'",false)','secondary')+btn('Review resolution / record explanation','workspace("draft")','secondary'));return}panel('Closing plenary: final decision','<p>All human country delegates have recorded no objection. Unassigned delegations accept the numerical package under their scripted mandates; free-text wording has been reviewed by the human drafting group.</p>',btn('Confirm plenary adoption','completePlenary()')+btn('Return to consultation','revise()','secondary'))}
 function plenaryPosition(id,accept){if(!committeePending||!assignments.some(a=>a.role===id&&id!=='chair'))return;if(!accept){Diplomacy.log('Plenary objection',Roles.get(id).name+' requested further consultation.');Diplomacy.invalidate();committeePending=false;plenaryVotes={};revise();return}plenaryVotes[id]='no objection';Diplomacy.log('Plenary position',Roles.get(id).name+': no objection.');plenary()}
 function completePlenary(){if(!committeePending||assignments.some(a=>a.role!=='chair'&&!plenaryVotes[a.role]))return;if(!Diplomacy.snapshot().committee||!Diplomacy.ready()){committeePending=false;notify('Text changed; repeat committee consideration.');revise();return}Diplomacy.adopt();committeePending=false;const date=new Date();finalAgreement=Agreement.create(state(),{id:'ASM-'+date.toISOString().slice(0,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,7).toUpperCase(),date:date.toISOString().replace('T',' ').slice(0,19)+' UTC',mode,opening,initialReporting,attempts,failures,roster:assignments.map((a,i)=>'Student '+(i+1)+': '+Roles.get(a.role).name).join('; '),history:proposalHistory});finalAgreement.diplomacy=Diplomacy.reportSections();if(proposalHistory.length){proposalHistory.at(-1).result='Adopted in closing plenary';finalAgreement.history=JSON.parse(JSON.stringify(proposalHistory));}speak('adopted',finishSession)}
 async function init(){$('dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog()});try{AssemblyScene.init()}catch(e){$('webglFallback').hidden=false;console.error(e)}try{const r=await fetch('dialogue.json?v=0.4');if(!r.ok)throw Error('dialogue');lines=await r.json()}catch{$('panel').innerHTML='<h2>Session unavailable</h2><p>Reload from the website or local server.</p>';return}welcome()}
 function welcome(){panel('Take your seat.','<p>Experience global health diplomacy, from your role briefing to a downloadable policy agreement.</p><div class="tag">3D CHAMBER · VOICED DELEGATIONS</div><p class="note">Choose a role. Understand its mandate. Negotiate from that perspective.</p>',btn('Explore the diplomacy workspace','workspace()')+btn('Take a guided tour','tour(0)')+'<button class="primary" onclick="AssemblyRooms.open()">Join a live classroom</button>'+btn('Solo practice','setup("solo")')+btn('Group practice · 2–5 students','setup("group")','secondary')+'<p class="micro-note">Groups use one shared screen. Unassigned roles are scripted. Fictional teaching scenario; no WHO affiliation.</p>')}
 function setup(m){mode=m;step=0;assignments=Array.from({length:m==='solo'?1:2},()=>({role:'',ready:false}));lobby()}
 function lobby(){panel(mode==='solo'?'Choose your role':'Allocate participant roles',`<p>${mode==='solo'?'Choose one of five perspectives. Other roles are scripted.':'Each student must choose a different role. Pass the controls between students; this version uses one shared screen.'}</p>${mode==='group'?'<label class="plan-field">Number of students<select aria-label="Number of students" onchange="Chamber.groupSize(this.value)">'+[2,3,4,5].map(n=>'<option '+(n===assignments.length?'selected':'')+'>'+n+'</option>').join('')+'</select></label>':''}<div class="role-assignment">${assignments.map((a,i)=>'<label class="plan-field">Student '+(i+1)+' role<select aria-label="Student '+(i+1)+' role" onchange="Chamber.assign('+i+',this.value)"><option value="">Choose a role…</option>'+Roles.all.map(r=>'<option value="'+r.id+'" '+(a.role===r.id?'selected ':'')+(assignments.some((b,j)=>j!==i&&b.role===r.id)?'disabled':'')+'>'+r.name+' · '+r.tag+'</option>').join('')+'</select></label>').join('')}</div><p id="lobbyError" role="alert"></p>`,btn('Read participant briefings','beginBriefings()')+btn('Back to practice options','resetSession()','textbutton'))}
 function groupSize(n){const count=Number(n);if(!Number.isInteger(count)||count<2||count>5)return;assignments=Array.from({length:count},(_,i)=>assignments[i]||{role:'',ready:false});lobby()}
 function assign(i,id){if(!Roles.get(id)||assignments.some((a,j)=>j!==i&&a.role===id)){assignments[i]={role:'',ready:false};lobby();return}assignments[i]={role:id,ready:false};updateSeat();lobby()}
 function beginBriefings(){if(!Roles.validate(mode,assignments)){$('lobbyError').textContent='Choose a different role for every student before continuing.';return}briefIndex=0;briefing()}
 function briefing(){const a=assignments[briefIndex];dialog('<span class="eyebrow">PRE-SIMULATION BRIEFING · STUDENT '+(briefIndex+1)+' OF '+assignments.length+'</span>'+roleContent(a.role)+'<label class="checklabel"><input id="briefReady" type="checkbox" '+(a.ready?'checked':'')+'> I have read my priorities, constraints and evidence.</label><p id="briefError" role="alert"></p>'+btn(briefIndex===assignments.length-1?'Confirm roles and continue':'Confirm and read next role','confirmBriefing()')+btn('Back to role allocation','backToLobby()','textbutton'))}
 function confirmBriefing(){if(!$('briefReady').checked){$('briefError').textContent='Read your briefing and tick the acknowledgement to continue.';return}assignments[briefIndex].ready=true;briefIndex++;if(briefIndex<assignments.length){briefing();return}closeDialog();readyRoom()}
 function backToLobby(){closeDialog();lobby()}
 function readyRoom(){panel('Ready for the assembly',assignments.map((a,i)=>'<div class="lineitem"><b>Student '+(i+1)+'</b><span>'+Roles.get(a.role).name+'</span></div>').join('')+'<p class="note">The Secretariat supplies evidence. '+(human('chair')?'Student '+(assignments.findIndex(a=>a.role==='chair')+1)+' chairs the meeting.':'A scripted Chair leads the meeting.')+' Unassigned country seats follow scripted mandates.</p><p>Human delegates choose interventions and explicitly record support or objection. Written mandates constrain available agreements.</p>',btn('Review agenda and procedure','workspace("procedure")','secondary')+btn('Adopt agenda and begin with audio','start(true)')+btn('Adopt agenda and begin with captions','start(false)','secondary')+btn('Change participant roles','lobby()','textbutton'))}


 const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function proposalEditor(){const s=state();dialog('<span class="eyebrow">NEGOTIATION WORKSPACE</span><h2>Build a workable agreement</h2><p>Discuss conditional offers aloud in group mode. In solo mode, use the scripted mandate feedback to explore trade-offs. This is not a live private-chat room.</p><div class="proposal-grid">'+Lab.countries.map((c,i)=>'<label class="plan-field">'+c.name+' allocation (%)<input id="allocation'+i+'" type="number" min="0" max="100" step="1" value="'+s.alloc[i]+'"></label>').join('')+'<label class="plan-field">Donor financing (m credits)<input id="offerFund" type="number" min="0" max="100" value="'+s.fund+'"></label><label class="plan-field">Delivery support (within financing)<input id="offerDelivery" type="number" min="0" max="100" value="'+s.delivery+'"></label></div><label class="checklabel"><input id="offerReporting" type="checkbox" '+(s.report?'checked':'')+'> Quarterly public reporting</label><label class="checklabel"><input id="offerGuarantee" type="checkbox" '+(s.guarantee?'checked':'')+'> Production purchase guarantee</label><p id="proposalError" role="alert"></p><div id="proposalResponses" class="terms-preview" aria-live="polite">Check responses to understand each scripted mandate before circulating.</div>'+btn('Check delegation responses','previewProposal()')+btn('Circulate this draft','circulateProposal()','secondary')+btn('Return to chamber','closeDialog()','textbutton'));}
 function readProposal(){const number=id=>$(id).value.trim()===''?NaN:Number($(id).value);return {alloc:[0,1,2,3].map(i=>number('allocation'+i)),fund:number('offerFund'),delivery:number('offerDelivery'),report:$('offerReporting').checked,guarantee:$('offerGuarantee').checked};}
 function previewProposal(){const p=readProposal(),error=Negotiation.validate(p);$('proposalError').textContent=error;if(error)return null;const s={...state(),...p};$('proposalResponses').innerHTML='<strong>Scripted mandate feedback</strong>'+Lab.countries.map((c,i)=>{const v=Lab.position(s,i);return '<p><b>'+c.name+': '+(v.yes?'Within mandate':'Needs revision')+'</b><br>'+v.reason+'</p>'}).join('')+'<p>Feedback is not a vote. Human delegates still record support or objection.</p>';return p;}
 function circulateProposal(){const p=previewProposal();if(!p)return;customDraft=p;report=p.report;guarantee=p.guarantee;delivery=p.delivery;closeDialog();choose('custom');}
 function negotiationRecord(){dialog('<h2>Negotiation record</h2>'+(proposalHistory.length?'<ol class="review-log">'+proposalHistory.map(p=>'<li><b>Draft '+p.number+' · '+esc(p.result)+'</b><p>'+esc(Negotiation.describe(p.terms))+'</p><p>'+esc(p.changes.join('; '))+'</p></li>').join('')+'</ol>':'<p>No revised drafts have been circulated yet.</p>')+btn('Return to simulation','closeDialog()','secondary'));}
 function reflect(){if(!finalAgreement)return;dialog('<span class="eyebrow">DEBRIEF · FROM EXPERIENCE TO LEARNING</span><h2>Why did agreement become possible?</h2><p>Step out of your delegation role. Record your own interpretation; there is no automatic grade.</p>'+['Which concession or clause made agreement possible?','Whose needs remain unmet, and why?','Who should act next, by when, and what would you monitor?'].map((q,i)=>'<label class="reflection-field">'+q+'<textarea id="reflection'+i+'" maxlength="600">'+esc(reflection[i])+'</textarea></label>').join('')+btn('Save reflection in the report','saveReflection()')+btn('Review negotiation record','negotiationRecord()','secondary')+btn('Return to simulation','closeDialog()','textbutton'));}
 function saveReflection(){reflection=[0,1,2].map(i=>Negotiation.cleanReflection($('reflection'+i).value));finalAgreement.reflection=[...reflection];downloaded=false;closeDialog();notify('Reflection added to your report. Download or save the updated version.');finishSession();}
 function saveToAccount(){if(!finalAgreement)return;window.AssemblyAccount.open(finalAgreement);}
 function tour(i=0){tourStep=Math.max(0,Math.min(3,i));const cards=[['Choose your role','Use the white panel on the right to choose solo or shared-screen group practice. Read the mandate before starting.'],['Listen and take the floor','Speech captions are at the bottom. Finish speech advances the narration. Camera buttons change the view; they do not advance the negotiation.'],['Make and revise an offer','Compose allocations and financing, check scripted responses, then circulate a draft. Human delegates decide whether to support it.'],['Reflect and keep your agreement','Test implementation, record your learning, and download the final PDF. Sign in to keep a copy or submit it to a class.']];const c=cards[tourStep];dialog('<span class="eyebrow">QUICK START · '+(tourStep+1)+' / 4</span><h2>Your guide to the assembly</h2><div class="tour-card"><strong>'+c[0]+'</strong><p>'+c[1]+'</p></div><div class="tour-actions">'+(tourStep?btn('Previous','tour('+(tourStep-1)+')','secondary'):'')+btn(tourStep===3?'Return to simulation':'Next',tourStep===3?'closeDialog()':'tour('+(tourStep+1)+')')+'</div><p class="micro-note">Independent WHO-inspired teaching scenario. Fictional countries, simplified consensus and illustrative implementation rules.</p>');}

 init();return {saveContribution,originalStatement,deliverOriginal,finishOriginal,workspace,saveParagraph,savePosition,saveResponsibilities,plenary,plenaryPosition,completePlenary,togglePanel,proposalEditor,previewProposal,circulateProposal,negotiationRecord,reflect,saveReflection,saveToAccount,tour,view,toggleSound,pause,skip,replay,start,brief,north,producer,floor,statement,consult,amend,shock,reporting,choose,decide,revise,setup,lobby,groupSize,assign,beginBriefings,confirmBriefing,backToLobby,roleBrief,roster,positionCheck,recordPosition,deliveryChange,implementation,savePlan,reviewAgreement,downloadAgreement,restart,resetSession,closeDialog,debrief,delegate,showDocument,showAbout};
})();


